plist.dict:
CFBundlePackageType
APPL
CFBundleName
{{.Info.ProductName}}
CFBundleExecutable
{{.OutputFilename}}
CFBundleIdentifier
com.wails.{{safeBundleID .Name}}
CFBundleVersion
{{.Info.ProductVersion}}
CFBundleGetInfoString
{{.Info.Comments}}
CFBundleShortVersionString
{{.Info.ProductVersion}}
CFBundleIconFile
iconfile
LSMinimumSystemVersion
10.13.0
NSHighResolutionCapable
true
NSHumanReadableCopyright
{{.Info.Copyright}}
{{if .Info.FileAssociations}}

CFBundleDocumentTypes

  {{range .Info.FileAssociations}}

    CFBundleTypeName
    {{.Name}}
    CFBundleTypeRole
    {{.Role}}
    CFBundleTypeIconFile
    {{.IconName}}
    LSItemContentTypes

      com.wails.{{safeBundleID $.Name}}.{{.Ext}}

    CFBundleTypeExtensions

      {{.Ext}}


  {{end}}


UTExportedTypeDeclarations

  {{range .Info.FileAssociations}}

    UTTypeIdentifier
    com.wails.{{safeBundleID $.Name}}.{{.Ext}}
    UTTypeDescription
    {{.Name}}
    UTTypeIconFile
    {{.IconName}}
    UTTypeConformsTo

      public.data

    UTTypeTagSpecification

      public.filename-extension

        {{.Ext}}



  {{end}}

{{end}}
{{if .Info.Protocols}}
CFBundleURLTypes

  {{range .Info.Protocols}}

        CFBundleURLName
        com.wails.{{.Scheme}}
        CFBundleURLSchemes

            {{.Scheme}}

        CFBundleTypeRole
        {{.Role}}

  {{end}}

{{end}}
NSAppTransportSecurity

    NSAllowsLocalNetworking
